- {"prov":[{"bbox":[280.24011,366.77972000000005,500.32104,414.90198],"page":3,"span":[0,318],"__ref_s3_data":null}],"text":"With combined experiences and direct access to development groups, we're the experts in IBM DB2® for i. The DB2 for i Center of Excellence (CoE) can help you achieve-perhaps reexamine and exceed-your business requirements and gain more confidence and satisfaction in IBM product data management products and solutions.","type":"paragraph","payload":null,"name":"Text","font":null}
