- {"prov":[{"bbox":[64.800003,154.45727999999997,247.02536,166.44528000000005],"page":11,"span":[0,31],"__ref_s3_data":null}],"text":"3.2.2 Built-in global variables","type":"subtitle-level-1","payload":null,"name":"Section-header","font":null}
- {"prov":[{"bbox":[136.8,119.07847000000004,518.00116,140.29128000000003],"page":11,"span":[0,161],"__ref_s3_data":null}],"text":"Built-in global variables are provided with the database manager and are used in SQL statements to retrieve scalar values that are associated with the variables.","type":"paragraph","payload":null,"name":"Text","font":null}
- {"prov":[{"bbox":[136.8,73.05927999999994,532.3385,106.27189999999996],"page":11,"span":[0,233],"__ref_s3_data":null}],"text":"IBM DB2 for i supports nine different built-in global variables that are read only and maintained by the system. These global variables can be used to identify attributes of the database connection and used as part of the RCAC logic.","type":"paragraph","payload":null,"name":"Text","font":null}
