{"prov":[{"bbox":[136.79997,610.2995,512.53802,631.51233],"page":8,"span":[0,126],"__ref_s3_data":null}],"text":"For example, the following CHGFCNUSG command shows granting authorization to user HBEDOYA to administer and manage RCAC rules:","type":"paragraph","payload":null,"name":"Text","font":null}
{"prov":[{"bbox":[136.80096,593.54877,441.59686,602.32355],"page":8,"span":[0,61],"__ref_s3_data":null}],"text":"CHGFCNUSG FCNID(QIBM_DB_SECADM) USER(HBEDOYA) USAGE(*ALLOWED)","type":"paragraph","payload":null,"name":"Text","font":null}
{"prov":[{"bbox":[64.800003,560.65729,544.47546,572.64532],"page":8,"span":[0,72],"__ref_s3_data":null}],"text":"2.1.7 Verifying function usage IDs for RCAC with the FUNCTION_USAGE view","type":"subtitle-level-1","payload":null,"name":"Section-header","font":null}
{"prov":[{"bbox":[136.8,525.2785,519.51794,546.49133],"page":8,"span":[0,130],"__ref_s3_data":null}],"text":"The FUNCTION_USAGE view contains function usage configuration details. Table 2-1 describes the columns in the FUNCTION_USAGE view.","type":"paragraph","payload":null,"name":"Text","font":null}
